    public static int btNl(byte[] b, int i) {
        int k = i;
        while ((k < emon.Port.blobLen(b)) && (emon.Port.blobU8(b, k) != 10)) {
            k += 1;
        }
        return k;
    }
    public static int btNext(byte[] b, int i, int lim, int ch) {
        // Index of the next byte `ch` in [i, lim), or lim.
        int k = i;
        while ((k < lim) && (emon.Port.blobU8(b, k) != ch)) {
            k += 1;
        }
        return k;
    }
    public static int btDigit(int c) {
        if ((c >= 48) && (c <= 57)) {
            return c - 48;
        }
        if ((c >= 65) && (c <= 70)) {
            return c - 55;
        }
        if ((c >= 97) && (c <= 102)) {
            return c - 87;
        }
        return -1;
    }
    public static int btNums(byte[] b, int from, int to, int base, emon.Port.Cells c) {
        // Parse the numbers (written in `base`, 10 or 16) separated by spaces in b[from, to) onto c, cleared first.
        // Answers how many.
        int k = from;
        int v = 0;
        int in = 0;
        int d = 0;
        emon.Port.cellsDrop(c, 0);
        while (k < to) {
            d = btDigit(emon.Port.blobU8(b, k));
            if ((d >= 0) && (d < base)) {
                v = (v * base) + d;
                in = 1;
            } else if (in == 1) {
                emon.Port.cellsPush(c, v);
                v = 0;
                in = 0;
            }
            k += 1;
        }
        if (in == 1) {
            emon.Port.cellsPush(c, v);
        }
        return emon.Port.cellsLen(c);
    }
    public static void testEveryClaimedRowOfBidiCharacterTestTxt() {
        byte[] f = emon.Testport.testFile("bidi/conformance.txt");
        emon.Port.Cells ar = emon.Port.newCells();
        emon.Port.Cells wantLv = emon.Port.newCells();
        emon.Port.Cells wantVis = emon.Port.newCells();
        int end = emon.Port.blobLen(f);
        int pos = 0;
        int line = 0;
        int rows = 0;
        int e = 0;
        int s1 = 0;
        int s2 = 0;
        int n = 0;
        int o = 0;
        int k = 0;
        int badl = 0;
        int badv = 0;
        while (pos < end) {
            line += 1;
            e = btNl(f, pos);
            if ((pos < e) && (emon.Port.blobU8(f, pos) != 35)) {
                rows += 1;
                s1 = btNext(f, pos, e, 59);
                s2 = btNext(f, s1 + 1, e, 59);
                emon.Port.cellsDrop(ar, 0);
                n = btNums(f, pos, s1, 16, ar);
                btNums(f, s1 + 1, s2, 10, wantLv);
                btNums(f, s2 + 1, e, 10, wantVis);
                o = Bidi.bdOrderOf(ar, 0, n);
                badl = 0;
                badv = 0;
                k = 0;
                while (k < n) {
                    if (emon.Port.cellsAt(ar, (o - n) + k) != emon.Port.cellsAt(wantLv, k)) {
                        badl += 1;
                    }
                    if (emon.Port.cellsAt(ar, o + k) != emon.Port.cellsAt(wantVis, k)) {
                        badv += 1;
                    }
                    k += 1;
                }
                emon.Testport.assertEqAt(badl, 0, "characters with a wrong level", line);
                emon.Testport.assertEqAt(badv, 0, "positions in the wrong visual order", line);
            }
            pos = e + 1;
        }
        emon.Testport.assertThat(rows > 1000, "the corpus has its rows");
    }
