                rows += 1;
                t1 = btNext(f, pos, e, 9);
                t2 = btNext(f, t1 + 1, e, 9);
                emon.Port.cellsDrop(shown, 0);
                emon.Port.cellsDrop(logical, 0);
                n = Model.textAppendUtf8(shown, f, pos, t1);
                m = Model.textAppendUtf8(logical, f, t1 + 1, t2);
                emon.Testport.assertEqAt(btShownAsLogical(shown, n, logical, ar), 1, "what is shown, put in logical order, is the logical text", line);
